    func nudge(dx: CGFloat, dy: CGFloat) -> Bool {
        var ops: [ReelOp] = []
        for id in selection.sorted() {
            guard let clip = snapshot.clip(id), snapshot.track(clip.track)?.locked != true
            else { continue }
            let props = editTarget.start(of: clip, in: project).video
            ops.append(
